import{_ as t,d as a,e as o,x as i}from"./chunks/framework.BRr8VP3a.js";const m=JSON.parse('{"title":"A choice with losses still calls for a reasoned bounded judgment","description":"Recommend within explicit premises while preserving unmet claims and the limits of authority.","frontmatter":{"title":"A choice with losses still calls for a reasoned bounded judgment","description":"Recommend within explicit premises while preserving unmet claims and the limits of authority."},"headers":[],"relativePath":"en/concepts/choices-with-loss.md","filePath":"en/concepts/choices-with-loss.md"}'),s={name:"en/concepts/choices-with-loss.md"};function n(r,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="a-choice-with-losses-still-calls-for-a-reasoned-bounded-judgment" tabindex="-1">A choice with losses still calls for a reasoned bounded judgment <a class="header-anchor" href="#a-choice-with-losses-still-calls-for-a-reasoned-bounded-judgment" aria-label="Permalink to &quot;A choice with losses still calls for a reasoned bounded judgment&quot;">​</a></h1><p><strong>Recommend within explicit premises while preserving unmet claims and the limits of authority.</strong></p><p>Sometimes every feasible option, including delay and no action, leaves legitimate claims unmet. The analysis should not invent a costless option or stop at questions. It can give a recommendation for deliberation, with the normative premises and decision rule made explicit.</p><p>State who bears the remaining losses, why their claims still hold, who owes mitigation, remedy, explanation, or review, and what would change the recommendation. If the decision rule is disputed, present the different resulting judgments without choosing on behalf of a qualified authority.</p><p>First test the apparent lack of alternatives: who controls the scarcity, whether prior decisions can be challenged, and whether options were excluded merely because they cost the decision maker. If authority is insufficient, refer the matter to a subject with authority rather than treating that gap as proof of no alternative. This showing remains open to appeal and goes to review independent of the decision maker.</p><p>Nonwaivable law and protection do not lapse because choices are painful. A claim that they cannot all be preserved must identify the conflicting requirements and excluded options for independent review. If that claim is not confirmed, return to options that do not cross those requirements. Even if confirmed, the framework does not endorse any option as authorized, and still-preservable protections continue. A competent actor needs its own applicable statutory or emergency authority, acts within the narrowest scope, bears responsibility, and sets expiry and subsequent review.</p><h2 id="keep-these-judgments-separate" tabindex="-1">Keep these judgments separate <a class="header-anchor" href="#keep-these-judgments-separate" aria-label="Permalink to &quot;Keep these judgments separate&quot;">​</a></h2><div class="xk-table"><table><thead><tr><th>Analytical recommendation</th><th>Real-world authorization</th></tr></thead><tbody><tr><td>A reasoned proposal with premises, costs, and revision conditions.</td><td>Valid authority and applicable protections for execution.</td></tr></tbody></table></div><h2 id="teaching-example-two-urgent-needs-one-available-worker" tabindex="-1">Teaching example: two urgent needs, one available worker <a class="header-anchor" href="#teaching-example-two-urgent-needs-one-available-worker" aria-label="Permalink to &quot;Teaching example: two urgent needs, one available worker&quot;">​</a></h2><p>Assume two needs compete for one worker and all feasible schedules cause some delay. A stated priority rule can support a bounded recommendation. The delayed person’s claim and the institution’s staffing responsibility remain on record.</p><p><strong>Assumptions:</strong> Hypothetical scarcity; no clinical triage instruction is given.</p><p><strong>Boundary:</strong> Actual professional or emergency decisions require the relevant competent procedure.</p><h2 id="check-your-reading" tabindex="-1">Check your reading <a class="header-anchor" href="#check-your-reading" aria-label="Permalink to &quot;Check your reading&quot;">​</a></h2><p><strong>Does choosing an option erase the losses that could not be avoided?</strong></p><p>No. The affected claims and subsequent responsibilities remain; the ledger must not remove them to make the choice look costless.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><p>Costs of waiting do not create authority to act.</p></li><li><p>Nonwaivable requirements cannot be traded away by a framework score.</p></li></ul><p>Read the complete <a href="/xi-kari-skill/handbook/en/theory/part-14.html#section-14-9-1">source section §14.9.1</a> and its guide. This explanation follows theory v2; the <a href="/xi-kari-skill/handbook/en/downloads.html">Chinese original</a> remains authoritative.</p>',18)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
